/// <summary>
/// Extension of <c>InventCostClosing</c> to trigger the inventory closing completed business event.
/// </summary>
[ExtensionOf(classStr(InventCostClosing))]
final class AAXInventCostClosing_Class_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the inventory closing completed business event after the closing process finishes.
/// </summary>
void run()
{
    next run();

    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXInventClosingCompletedBusinessEvent)))
    {
        AAXInventClosingCompletedBusinessEvent::construct(this.parmTransDate()).send();
    }
}
